WITH base AS (SELECT *, LENGTH(country) country_length FROM suppliers WHERE city NOT IN ('Chiang Mai', 'Tokyo')) SELECT id, supplier_name, city, country_length, SUM(country_length) OVER (PARTITION BY country) country_sum_country_length, MAX(country_length) OVER w_running city_max_country_length, LEAD(rating, 1) OVER (ORDER BY rating, id) next_rating, STDDEV_SAMP(country_length) OVER w_running city_stddev_samp_country_length FROM base WHERE country_length != 46 WINDOW w_running AS (PARTITION BY city);
